void print_flag(const std::string& input){
    vector<int> xor_key = {22,38,62,20,12,21,34,28,75,89,8,60,84,10,124,59,7,84,43,1,102,31,9,64,0,73,88,58,1,32,66,53,25,10,61,19,43,56,3,1,57,104,1,76,41,16,86,54,69,90,30,33,27,46,70,30,52,88,5,30,26,34,96,94,17,55,53,61,13,10,85,43,11,56,101,84,33,107,126,121,87,84,96,69,19};
    for ( int i = 0; i < input.length(); i++){
        cout << (char)(xor_key[i] ^ (int) input[i] ) ;
    }
    cout << endl;
}

int main(){
    string input;
    long long checksum = 0;
    cout << "Enter the password: ";
    cin >> input;
    if (input.length() != 85) {
        cout << "Incorrect." << endl;
        return 1;
    }
    check(input, &checksum);
    if (checksum == 147107LL){
        cout << "Correct! Here is your flag: ";
        print_flag(input);
    } else {
        cout << "Incorrect." << endl;
    }
    return 0;
}
